INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('gcp-ace', 'GCP ACE 弱点問題集', '模試で間違えた問題を反復演習', '#1565C0', 0)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('IAM・組織ポリシー', '#E65100', 0),
  ('コンピュート・VM', '#1565C0', 1),
  ('GKE', '#6A1B9A', 2),
  ('ストレージ', '#00838F', 3),
  ('ネットワーク', '#AD1457', 4),
  ('サーバーレス', '#2E7D32', 5),
  ('監視・ログ', '#F9A825', 6),
  ('データ分析', '#5D4037', 7),
  ('運用・CLI', '#37474F', 8)
) AS v(name, color, sort_order)
WHERE s.slug = 'gcp-ace'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, options, correct_index, explanation, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.options::jsonb, v.correct_index, v.explanation, v.w
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('m2q2', 'IAM・組織ポリシー', '全ての開発チームは米国拠点。各チームが米国内でのみクラウドリソースを作成できるようアクセスを制限したい。どうすべき？', '["全開発プロジェクトを格納するフォルダを作成し、USロケーションでリソースを制限する組織ポリシーを作成","全開発プロジェクトを格納する組織を作成し、USリージョンで制限するIAMポリシーを作成","米国のリソースロケーションを制限するIAMポリシーを作成し、全開発プロジェクトに適用","リソースロケーションを制限するIAMポリシーを作成し、全開発ロールに適用"]', 0, '「場所の制限」は組織ポリシー（gcp.resourceLocations）の仕事。IAMでは場所を制限できない。複数プロジェクトへの一括適用はフォルダにまとめてポリシー継承させる。', 1),
  ('m2q18', 'IAM・組織ポリシー', 'ドメイン外メールアドレスのユーザーが複数発見された。不一致ユーザーを削除し、今後のリソース監査を不要にしたい。どうすべき？', '["Cloud Schedulerタスクで定期的にプロジェクトをスキャンして削除","Cloud Schedulerタスクで定期的にリソースをスキャンして削除","組織ポリシーでドメイン制限し、不一致ユーザーを自動的に削除","組織ポリシーでドメイン制限し、既存の不一致ユーザーを事後的に削除"]', 3, '組織ポリシーは「将来の新規操作」にのみ適用される。既存の違反は自動削除されない。「ポリシー設定＋既存違反を手動削除」の2ステップが常に正解。', 1),
  ('m2q21', 'IAM・組織ポリシー', 'Google Workspace使用中。2年で100人→1000人に成長予定。複雑さやセキュリティ問題なく10倍成長をサポートするには？', '["ユーザーをActive Directoryに移行しGCDSを有効化","Cloud Identityでユーザーをグループに編成し、MFAを適用","Cloud IdentityとGoogle Workspace間のIDフェデレーションを有効化","サードパーティIdPサービスをフェデレーション経由で使用"]', 1, 'Google Workspaceを使っている＝Cloud Identity（IDとグループを管理する基盤）が最初から含まれている。「グループにロールを付与」する設計なら、100人→1000人でも追加設定は人をグループに入れるだけ。MFAもCloud Identityで一括設定可能。×A：Active Directoryへの移行は不必要な複雑さ（既存Google環境が使える）。×C・D：IDフェデレーション＝「別会社の社員証（外部IdP）をそのままGCPに使わせる仕組み」。OktaやAzure ADなど社外IdPが既にある場合に使うものであり、Google Workspaceだけで完結する今回の構成には不要。', 1),
  ('m2q33', 'IAM・組織ポリシー', 'DevOpsグループにCompute Engineリソースの完全制御を与え、他リソースの作成・更新権限は持たせたくない。Googleの推奨は？', '["基本ロールroles/viewerと事前定義ロールroles/compute.adminを付与","compute.instanceAdmin.*権限のIAMポリシーを作成しアタッチ","フォルダレベルでカスタムロールを作成しcompute.instanceAdmin.*権限を付与","基本ロールroles/editorを付与"]', 0, 'compute.adminはCompute Engine全体（VM＋ディスク＋NW＋FW）の管理権限。instanceAdminはVMだけで「完全制御」に足りない。viewerで他リソースは閲覧のみ。editorは広すぎ。事前定義ロール優先。', 1),
  ('m3q3', 'IAM・組織ポリシー', '会社にSAML対応のSSO IdPがある。ユーザーはCloud Identityに存在。会社のSSOプロバイダで認証させたい。どうすべき？', '["Cloud IdentityでGoogleをIdPとしてカスタムSAMLアプリのSSOをセットアップ","Cloud IdentityでサードパーティIdPを使用するSSOをセットアップし、GoogleをSPとして設定","OAuth2.0認証情報を取得しモバイル/デスクトップアプリのOAuthをセットアップ","OAuth2.0認証情報を取得しウェブサーバーアプリのOAuthをセットアップ"]', 1, 'Cloud Identity＝Googleのユーザー管理基盤（アカウント作成・グループ・MFAを管理する部門）。登場人物：IdP（Identity Provider）＝「あなたは本物」と証明する側＝会社のSSOシステム。SP（Service Provider）＝証明書を受け取ってサービスを提供する側＝Google。例え：会社の入館証（SSO）を見せれば社食（Google）を使える仕組みを作るのがB。×A：「GoogleをIdP」＝逆向き（GoogleログインをベースにしてSSOが使えなくなる）。×C・D：OAuthは「認可（誰が何のリソースにアクセスできるか）」のプロトコルで、「誰であるかの認証」には使わない。SAMLのみが認証フェデレーションに対応。', 1),
  ('m3q8', 'IAM・組織ポリシー', '開発環境と同じプロジェクトに本番環境を作る予定だったが、セキュリティチームが2環境間のネットワークルートの存在を禁止した。どうすべき？', '["新しいプロジェクトを作成しAPIを有効化、開発環境のセットアップを複製","既存VPCに本番用サブネットと本番用Cloud SQLを作成しデプロイ","既存VPCを共有VPC化し新プロジェクトと共有してデプロイ","別部門の本番プロジェクトに編集者ロールを依頼しデプロイ"]', 0, 'プロジェクトはデフォルトで独立したVPCを持つ＝別プロジェクトを作るだけでネットワーク分離が自動的に実現。同じVPC内のサブネット分けではルートが残る。共有VPCは逆に通信を可能にする。', 1),
  ('m3q9', 'IAM・組織ポリシー', '組織で「ドメイン制限共有」ポリシーが有効（自社Cloud Identityドメインのみ許可）。外部監査人にプロジェクトの閲覧のみ許可したい。どうすべき？', '["監査人のGoogleアカウントにviewerロールを付与","監査人のGoogleアカウントにSecurity Reviewerロールを付与","Cloud Identityに監査人用の一時アカウントを作成しviewerロールを付与","Cloud Identityに一時アカウントを作成しSecurity Reviewerロールを付与"]', 2, 'ドメイン制限共有が有効＝外部アカウントはIAMに追加不可。自社ドメインに一時アカウントを作るのが唯一の方法。「全リソースの閲覧」はviewer。Security Reviewerはセキュリティ構成専用で範囲が狭い。', 1),
  ('m3q14', 'IAM・組織ポリシー', 'web-applicationsプロジェクトのVMがcrm-databases-projのBigQueryデータセットにアクセスする必要がある。Googleの推奨は？', '["web-applicationsのプロジェクトオーナーにcrm-databases-projの適切なロールを付与","両プロジェクトにプロジェクトオーナーロールを付与","crm-databases-projにオーナーロール、web-applicationsにbigquery.dataViewerを付与","crm-databases-projにbigquery.dataViewerロールを付与し、web-applicationsに適切なロールを付与"]', 3, '権限は「リソースが置いてある側」（crm-databases-proj）で設定する。SAの住民票がどこにあるかは無関係。閲覧だけならdataViewer（最小権限）。オーナーは過剰。', 1),
  ('m3q16', 'IAM・組織ポリシー', 'カスタムIAMロールの最初のバージョンを作成。全権限は本番使用に適している必要があり、組織にステータスを明確に共有したい。どうすべき？', '["権限はsupportedサポートレベルを使用し、ロールのステージをALPHAに設定","権限はsupportedサポートレベルを使用し、ロールのステージをBETAに設定","権限はtestingサポートレベルを使用し、ロールのステージをALPHAに設定","権限はtestingサポートレベルを使用し、ロールのステージをBETAに設定"]', 0, '2つの独立した概念を区別することがカギ。①権限のサポートレベル（supported vs testing）：各権限が本番で安定して使えるかどうかの品質ラベル。「全権限が本番使用に適切」→supported一択。testingはGoogleが将来変更・廃止する可能性があり本番NG。②ロールのステージ（ALPHA/BETA/GA）：ロール全体が組織内でどの開発フェーズかを示すラベル。「最初のバージョンを明確に共有」→ALPHA（「まだ育成中の初版」という宣言）。よくある混同：「本番に使う＝GA」ではない。GAはロールの完成度の話であり、ロールがALPHAでも権限がsupportedなら実際の本番リソースへの操作は安全。', 1),
  ('m3q32', 'IAM・組織ポリシー', 'ADC（Application Default Credentials）で認証するアプリを開発PCからCompute Engine VMに移行する。最小限の変更で認証をセットアップするには？', '["Compute Engine VMが使用するサービスアカウントに適切なアクセス権を割り当てる","適切なアクセス権を持つ新しいサービスアカウントを作成しアプリで構成","サービスアカウントの認証情報を構成ファイルに保存しアプリと共にデプロイ","ユーザーアカウントの認証情報を構成ファイルに保存しデプロイ"]', 0, 'ADCはVM上では「VMにアタッチされたSA」を自動的に使う。VMには既にデフォルトSAが付いているので新規作成不要、コード変更も不要。認証情報のファイル保存は漏洩リスクでNG。', 1),
  ('m3q46', 'IAM・組織ポリシー', '引き継いだプロジェクトで、プロジェクトオーナーロールが付与されているユーザーを確認したい。どうすべき？', '["コンソールでプロジェクト全体のSSH鍵を確認","Identity-Aware Proxyでリソースの権限をチェック","全リソースの監査ログを有効にし結果を検証","gcloud projects get-iam-policyコマンドで現在のロール割り当てを表示"]', 3, '現在のIAMポリシー（誰にどのロールが付いているか）を見る最も直接的な方法がget-iam-policy。監査ログは過去の変更履歴であり現在の状態確認には遠回り。', 1),
  ('m2q23', 'コンピュート・VM', 'マネージドインスタンスグループが新インスタンスの作成失敗アラートを発生させた。解決するには？', '["有効な構文の新インスタンステンプレートを作成し、インスタンス名と同名の永続ディスクを削除","新テンプレートを作成し、テンプレート内でインスタンス名とディスク名が同じでないことを確認","既存テンプレートの構文を確認し、同名ディスクを削除し、autoDeleteをtrueに設定","現テンプレートを削除して新テンプレートに置き換え、ディスク名を確認"]', 0, 'テンプレートは更新不可＝新規作成して差し替え。作成失敗の典型原因は同名の永続ディスクの残存。MIG参照中のテンプレートは削除できないので「先に削除」の選択肢はNG。', 1),
  ('m2q26', 'コンピュート・VM', '毎晩実行されるフォールトトレラントなバッチ（一部VM終了許容）。VMコストが高すぎる。どうすべき？', '["模擬メンテナンスイベントでテストし、成功したらスポットN2スタンダードVMを使用","模擬メンテナンスイベントでテストし、成功したらN2スタンダードVMを使用","MIGでテストし、成功したらMIGでN2スタンダードVMを使用","N1スタンダードVMでテストし、成功したらN1を使用"]', 0, '「フォールトトレラント＋一部終了OK」＝スポットVMの典型ユースケース（最大91%割引）。模擬メンテイベントで中断耐性を事前検証する。VM世代変更（N2→N1）だけでは大幅削減にならない。', 1),
  ('m2q38', 'コンピュート・VM', 'オンプレのデータ分析バイナリ群が毎晩45分、1〜16GBのファイルをメモリ処理する。最小の手間とコストでGCPに移行するには？', '["バイナリをコンテナ化しCloud SchedulerでCloud Runジョブを起動","バイナリをコンテナ化しGKE Standardにデプロイ","コードをCloud Functionsにアップロードしスケジュール起動","Compute Engine VMにリフト＆シフトし、インスタンススケジュールで起動／停止"]', 3, '「最小の手間」＝コンテナ化もリファクタリングも不要なリフト＆シフト。インスタンススケジュールで毎晩45分だけ起動すればコストも最小。バイナリ群はCloud Functionsの実行モデルに不適。', 1),
  ('m3q10', 'コンピュート・VM', '重要ワークロードのブートディスクを定期バックアップしたい。災害時に迅速復元、古いバックアップの自動クリーンアップも必要。どうすべき？', '["Cloud Functionsでインスタンステンプレートを作成","希望の間隔でディスクにスナップショットスケジュールを作成","Cronジョブでgcloudを使いディスクから新ディスクを作成","Cloud Tasksでイメージを作成しCloud Storageにエクスポート"]', 1, 'スナップショットスケジュール＝定期作成＋保持期間設定（自動削除）＋迅速復元を全部満たす組み込み機能。カスタム実装（Functions/Cron）は組み込み機能があるのに作るのは非推奨。', 2),
  ('m3q26', 'コンピュート・VM', '350GBのゾーンSSD永続ディスクで過剰な読み取りスロットリングが発生。コスト最小で最大スループットを提供するには？', '["ディスクのサイズを1TBに増やす","インスタンスのCPUを増やす","ローカルSSDに移行する","リージョンSSDに移行する"]', 0, 'SSD PDの性能はディスクサイズに比例し、1TBまで線形にスケールする。サイズを増やすだけで性能が上がる＝最も安い解決策。ローカルSSDは高額＋VM停止でデータ消滅。', 1),
  ('m3q29', 'コンピュート・VM', '事業買収によるトラフィック増加に対応するため、カスタムCompute Engine VMのコピーを作成する必要がある。どうすべき？', '["ベースVMのスナップショットを作成し、そのスナップショットからイメージを作成（してスナップショットからインスタンス作成）","ベースVMのスナップショットを作成し、そのスナップショットからインスタンスを作成","スナップショットからカスタムイメージを作成し、そのイメージからイメージを作成","スナップショットからカスタムイメージを作成し、そのイメージからインスタンスを作成"]', 3, '量産・スケール対応の正攻法：スナップショット→カスタムイメージ→インスタンス。イメージは再利用可能なテンプレート。スナップショットから直接は1〜2台の一時的対応向け。', 1),
  ('m3q34', 'コンピュート・VM', '月1回・約30時間のバッチプロセス。オフライン実行可。中断された場合は再開（やり直し）が必要。コスト最小でクラウド移行するには？', '["Compute EngineのプリエンプティブルVMに移行","GKEクラスタのプリエンプティブルノードに移行","Compute Engine VMに移行し、必要に応じて起動・停止","プリエンプティブルVMのテンプレートでMIGを作成しCPU使用率を調整"]', 2, '「中断＝やり直し」のジョブにプリエンプティブル（Spot）は絶対NG。29時間目に停止されたら全部無駄。月1回だけ通常VMを起動→完了後停止が最小コストで確実。', 1),
  ('m3q42', 'コンピュート・VM', '平日9-18時使用のアプリのVMを毎日バックアップし30日間保持したい。管理オーバーヘッドとサービス数を最小に。どうすべき？', '["インスタンスのメタデータにsnapshot-schedule/snapshot-retentionを追加","コンソールのディスクページでスナップショットスケジュールを作成（毎日・午前1-2時・30日後自動削除）","スナップショット作成と削除のCloud Functionsを作成しSchedulerでトリガー","ディスク内容をGCSにコピーするbashスクリプト＋crontab"]', 1, 'スナップショットスケジュールは頻度・開始時刻・保持期間を設定するだけの組み込み機能。メタデータでの設定は存在しない。Functions/scriptは管理オーバーヘッドが高い。', 2),
  ('m3q45', 'コンピュート・VM', 'us-central1-aのVMでアプリをホスト中。単一ゾーン障害をサポートし、ダウンタイムを排除し、コストを最小に。どうすべき？', '["us-central1-bにもリソースを作成し、両ゾーンに負荷を分散","us-central1-aでMIGを作成しヘルスチェックを短い間隔で構成","HTTPSロードバランサーとグローバル転送ルールを作成","定期バックアップ＋アラート＋障害時に手動復元"]', 0, 'ゾーン障害対策の基本＝複数ゾーンにリソースを分散して負荷分散。単一ゾーンのMIGはゾーン全体障害に無力。LBだけ作ってもバックエンドが1ゾーンなら意味なし。手動復元は「ダウンタイム排除」に反する。', 1),
  ('m3q50', 'コンピュート・VM', 'Googleアカウントを使わない新しい運用パートナーに、Linux VMへのアクセスを許可する必要がある。どうすべき？', '["Cloud IAPを有効にしIAPトンネルユーザーとして追加","ネットワークタグ＋ポート22のTCPアクセスを許可するFWルール","Cloud VPNをパートナーの内部ネットワークとの間にセットアップ","パートナーにSSHキーペアを生成してもらい、公開鍵をVMに追加"]', 3, 'Linux VMの標準認証はSSHキーベース。Googleアカウント不要で安全。IAPはGoogleアイデンティティ前提なので要件に合わない。FWやVPNは経路の話で認証手段ではない。', 1),
  ('m2q39', 'GKE', 'prod-cluster（Standard）とdev-cluster（Autopilot）を作成済み。kubectl get nodesでprodのノードしか表示されない。dev-clusterのノードを確認するには？', '["gcloud container clusters get-credentials dev-cluster → kubectl get nodes","gcloud container clusters update -generate-password dev-cluster → kubectl get nodes","kubectl config set-context dev-cluster → kubectl cluster-info","kubectl config set-credentials dev-cluster → kubectl cluster-info"]', 0, '新しいクラスタの操作はget-credentialsで認証情報を取得＋コンテキスト切り替えが必須。set-contextは既にkubeconfigに登録済みのクラスタの切り替え専用。', 1),
  ('m2q43', 'GKE', '検証可能なノードのIDと整合性が必要。ノードはインターネットからアクセス不可。クラスタ管理の運用コストも削減したい。どうすべき？', '["プライベートAutopilotクラスタをデプロイ","パブリックAutopilotクラスタをデプロイ","Standardパブリッククラスタでシールドノードを有効化","Standardプライベートクラスタでシールドノードを有効化"]', 0, '3要件の同時充足：①検証可能なノードID＝シールドノード（Autopilotはデフォルト有効）②インターネット不可＝プライベート③運用コスト削減＝Autopilot。プライベートAutopilotが唯一全部満たす。', 1),
  ('m2q47', 'GKE', 'ワークロードのリソース要件が不明で変動する。CPU/メモリの費用対効果の高い推奨事項と、あらゆる状況で一貫して機能するソリューションが必要。どうすべき？', '["HPAを可用性のために構成し、Cluster Autoscalerを提案のために構成","HPAを可用性のために構成し、VPAの推奨事項を提案のために構成","VPAの推奨事項を可用性のために構成し、Cluster Autoscalerを提案のために構成","VPAの推奨事項を可用性のために構成し、HPAを提案のために構成"]', 1, '可用性＝HPA（Pod数を自動増減して負荷対応）。リソース推奨値＝VPA推奨モード（CPU/メモリの適正値を分析）。Cluster AutoscalerはNode数の増減でPodの推奨とは無関係。', 1),
  ('m2q50', 'GKE', 'GKEアプリの一部はダウンタイム許容（フォールトトレラントでない）、他はクリティカルで常時稼働が必要。コスト最適化するには？', '["Standard VM単一ノードプール＋フォールトトレラントにspot_trueラベル","スポットVM単一ノードプール＋クリティカルにspot_falseラベル","両ノードプール作成、クリティカル→スポット、フォールトトレラント→Standard","両ノードプール作成、クリティカル→Standard、フォールトトレラント→スポット"]', 3, 'クリティカル＝Standard VMノードプール（停止されない）。ダウンタイム許容＝スポットVMノードプール（最大91%割引）。絶対に逆にしない。単一プールでは分離不可。', 1),
  ('m3q6', 'GKE', 'データサイエンティストチームが不定期にGPUを利用。再起動できない長時間ジョブ。コストを最小限に抑えるには？', '["GKEクラスタでノード自動プロビジョニング（NAP）を有効化","ワークロードにVertical Pod Autoscalerを作成","プリエンプティブル（Spot）VMとGPU付きノードプールを作成","GPU付きノードプールを最小サイズ1でオートスケーリング有効化"]', 0, 'NAP＝GPUを要求するPodが来たときだけGPUノードプールを自動作成し、終了後に削除。「不定期」＝常時起動は無駄、「再起動不可」＝Spotは危険。NAPだけが両立する。', 1),
  ('m3q47', 'GKE', '同じサブネットで複数のVPCネイティブGKEクラスタを運用中。ノードのIPアドレスが枯渇。ノードを増やせるようにするには？', '["同じリージョンに新しいサブネットを作成","GKEクラスタが使うサブネットにエイリアスIP範囲を追加","新しいVPCを作成し既存VPCとピアリング","クラスタに関連するサブネットのCIDR範囲を拡張"]', 3, 'VPCネイティブクラスタでは、ノードIPはサブネットのプライマリ範囲から割り当てられる。プライマリ範囲の拡張（縮小は不可）で解決。エイリアスIPはPod用でノードには効かない。', 1),
  ('m2q14', 'ストレージ', '病院の医療画像をオンプレからCloud Storageへ。新しい画像を自動アップロードするプロセスが必要。どうすべき？', '["Pub/SubトピックにCloud Storageトリガーを有効化し画像を送信するアプリを作成","gcloud storageコマンドで同期するスクリプトを作成しcronジョブでスケジュール","Pub/Subトピック＋Cloud FunctionでGCSに書き込み","コンソールから画像をバケットにアップロード"]', 1, 'オンプレからのファイル同期＝gcloud storage rsync＋cron。Pub/Subはメッセージングサービスで大容量ファイル転送には不向き。手動アップロードは「自動」の要件に反する。', 1),
  ('m2q32b', 'ストレージ', 'ビジネスクリティカルなアプリ。ゾーン障害が発生してもデータが即座に利用可能であることを確認したい。どうすべき？', '["ゾーン永続ディスク＋スナップショットスケジュール、障害時に復元してアタッチ","ゾーン永続ディスク、障害時に別ゾーンでアタッチ","リージョナル永続ディスク＋スナップショット、障害時に復元してアタッチ","リージョナル永続ディスクを使用し、障害時に別ゾーンのVMにアタッチ"]', 3, 'リージョナルPDは2ゾーンに同期複製済み＝障害時にそのまま別ゾーンで使える（即座）。スナップショット復元は時間がかかり「即座」ではない。ゾーンPDはゾーン障害時に使用不可。', 1),
  ('m2q46', 'ストレージ', 'アプリは過去30日以内のファイルのみアクセスする。アクセスされなくなったファイルのコストを自動的に節約したい。どうすべき？', '["ライフサイクルルールで30日超のオブジェクトをArchiveストレージに変更","Cloud Scheduler＋Cloud Functionsで30日以上前のファイルを毎日削除","30日間の保持ポリシーを作成しバケットをロック","バージョニングを有効にし30日後に非現行バージョンを期限切れに"]', 0, '「アクセス頻度低下＋コスト削減」＝ライフサイクルでストレージクラスを自動変更。削除ではなくクラス変更でデータは保持。保持ポリシーは「削除禁止」でコスト削減と無関係。', 1),
  ('m2q48', 'ストレージ', '請求書を5年保持・最大5リビジョン保存・365日超は低コスト層へ移動。運用と開発コストを最小に。どうすべき？', '["保持ポリシー＋Scheduler/Functionsでメタデータに基づき移動・削除","保持ポリシー＋ライフサイクルルールでクラス変更・バージョン数設定・削除","バージョニング＋Scheduler/Functionsで移動・削除","バージョニング＋ライフサイクル条件でクラス変更・バージョン数設定・古いファイル削除"]', 3, 'リビジョン保持＝バージョニング。クラス変更・バージョン数制御・期限削除＝全部ライフサイクルルールの組み込み機能。保持ポリシーは「削除禁止」で自動移動の機能はない。', 1),
  ('m3q5', 'ストレージ', 'データウェアハウスのアーカイブをCloud Storageに保存。規制要件で四半期に一度アクセスが必要。コスト効率の高いストレージは？', '["Coldlineストレージ","Nearlineストレージ","Regionalストレージ","Multi-Regionalストレージ"]', 0, 'アクセス頻度で選ぶ：Standard＝頻繁／Nearline＝月1回／Coldline＝四半期に1回（90日）／Archive＝年1回以下。「四半期に一度」はColdlineがぴったり。', 1),
  ('m2q4', 'ネットワーク', 'subnet-aのDBサーバーへ、subnet-bのアプリサーバーからのDBトラフィックのみを許可するFWルールを設定したい。どうすべき？', '["SA sa-app/sa-dbを作成・関連付けし、sa-app→sa-dbを許可するイングレスFWルールを作成","ネットワークタグを作成し、app-server→db-serverを許可するエグレスFWルールを作成","SAとネットワークタグを混在させVPC IP→subnet-a IPのイングレスルールを作成","タグとSAを混在させ、app-server→sa-dbのエグレスFWルールを作成"]', 0, '受信側（DB）を守るのでイングレスルール。ターゲットと送信元はサービスアカウントで指定するのがベストプラクティス（IPは変動する）。SAとタグの混在は管理が複雑になるので統一する。', 1),
  ('m2q12', 'ネットワーク', 'サブネットのIP範囲10.0.0.0/20でプライマリ内部IPが不足。VMにもっとIPを提供するには？', '["セカンダリIP範囲10.1.0.0/20を追加","IP範囲を10.0.0.0/18に変更","IP範囲を10.0.0.0/22に変更","IPv4からIPv6に変換"]', 1, 'CIDRは数字が小さいほどIPが多い（/20＝4096個、/18＝16384個）。拡張は可能・縮小は不可。セカンダリIP範囲はPod/Service用エイリアスIPでVMのプライマリIPには使えない。', 1),
  ('m3q25', 'ネットワーク', 'ポート443でSSL暗号化されたTCPトラフィック（非HTTP）を受信。クライアントは世界中。レイテンシを最小化するLBは？', '["HTTPSロードバランサー","ネットワークロードバランサー","SSLプロキシロードバランサー","内部TCP/UDPロードバランサー"]', 2, 'SSL暗号化TCP（非HTTP）＋グローバル＝SSLプロキシLB一択。HTTPSはHTTP専用。ネットワークLBはリージョナルでグローバル不可。内部LBはVPC内部専用。', 1),
  ('m3q40', 'ネットワーク', 'VPNでWANに接続されたVPCに新しいVMをデプロイ。公開インターネットトラフィックがVMにルーティングされないようにするには？', '["公開IPアドレスを持たずにインスタンスを作成","プライベートGoogleアクセスを有効にしてインスタンスを作成","VPCで全てを拒否するエグレスFWルールを作成","全トラフィックをVPNトンネル経由でルーティングするルートを作成"]', 0, '公開IPがない＝インターネット上に住所がない＝そもそも到達できない。最もシンプルで強固。プライベートGoogleアクセスは「VMから外へ」の通信用で受信とは無関係。エグレスFWも「出る」方向。', 1),
  ('m3q49', 'ネットワーク', 'データ流出を懸念するユーザーのため、開いている流出（egress）ポートを最小限に抑えたい。どうすべき？', '["全流出をブロックする優先度の低い（65534）ルール＋適切なポートのみ許可する優先度の高い（1000）ルール","受信ポートと流出ポートをペアにする優先度の高い（1000）ルール","全流出をブロックする優先度の高い（1000）ルール＋許可する優先度の低い（65534）ルール","適切なポートを許可する優先度の高い（1000）ルールのみ"]', 0, 'FW優先度は数字が小さいほど高い。「許可リスト方式」＝低優先度で全拒否を敷き、高優先度で必要なものだけ許可。逆にすると全拒否が先に評価され許可ルールが無意味になる。', 1),
  ('m2q5', 'サーバーレス', '特定のCMSソリューションを迅速かつ簡単にデプロイ・インストールしたい。どうすべき？', '["Cloud MarketplaceでCMSを検索し、gcloud CLIでデプロイ","Cloud MarketplaceでCMSを検索し、Marketplaceから直接デプロイ","TerraformとMarketplace IDでデプロイ","CMSプロバイダのインストールガイドに従い構成管理システムでインストール"]', 1, '「迅速かつ簡単」＝Marketplaceのウェブインターフェースから直接デプロイ（クリック操作）。CLIやTerraformは技術的に可能だが「簡単」ではない。', 2),
  ('m2q31', 'サーバーレス', 'Dockerイメージを作成済み。インフラを管理したくない。人気上昇に応じて自動スケールが必要。どうすべき？', '["コンテナイメージ入りインスタンステンプレート＋オートスケーリングMIG","DockerイメージをArtifact Registryにアップし、GKE Standardにデプロイ","DockerイメージをCloud Storageにアップし、GKE Standardにデプロイ","DockerイメージをArtifact Registryにアップし、Cloud Runにデプロイ"]', 3, 'Docker＋インフラ不要＋自動スケール＝Cloud Run一択。GKE StandardはNode管理が必要。Dockerイメージの保存先はArtifact Registry（Cloud Storageではない）。', 1),
  ('m2q34', 'サーバーレス', 'Pythonの複雑なマイクロサービス群がDockerコンテナで稼働中。設定は環境変数で注入。サーバーレスなGCPソリューションにデプロイするには？', '["既存CI/CDとDockerイメージを使いCloud Runにデプロイ。設定とエンドポイントを更新","既存CI/CDとDockerイメージを使いCloud Functionsにデプロイ。オンプレと同じ設定を使用","既存コードベースを個別のCloud Functionsとしてデプロイし設定を更新","既存コードベースを個別のCloud Runとしてデプロイ。オンプレと同じ設定を使用"]', 0, 'Cloud Run＝「Dockerコンテナごと持ち込んで動かす」。HTTPサーバーとして動く既存コンテナをほぼそのまま移行できる。Cloud Functions＝「関数1つのコードだけ渡す」FaaS。DockerイメージをCloud Functionsに直接デプロイする機能は存在しない。×B：技術的に不可（DockerイメージはFunctionsにデプロイできない）。×C：複雑なマイクロサービス全体を関数単位に書き直す必要があり、最小限の変更での移行に反する。×D：個別に分解する必要があり書き直しが発生。また「オンプレと同じ設定（IPやURL）」はクラウド移行時に必ず変わるので非現実的。', 1),
  ('m2q44', 'サーバーレス', 'Flaskウェブアプリ＋バックエンドAPI＋スケジュールされた長時間ETLジョブをサーバーレスに移行。運用コストを低く。どうすべき？', '["ウェブをApp Engine、APIをCloud Run、バッチをCloud TasksでCompute Engineで実行","ウェブをApp Engine、APIをCloud Run、バッチをCloud TasksでCloud Runで実行","ウェブをCloud Storageバケット、APIをCloud Run、バッチをCloud Runで実行","ウェブをCloud Storageバケット、APIをCloud Run、バッチをCompute Engineで実行"]', 1, '3コンポーネント別に最適サービスを選ぶ問題。①FlaskウェブアプリはApp Engine：「PythonのWebフレームワークをコードだけ渡せばGoogleが動かしてくれる」サービス。②APIはCloud Run：DockerでHTTPサーバーを動かすのに最適。③長時間ETLバッチはCloud Tasks＋Cloud Run：Cloud Tasksがスケジューリングし、Cloud RunでJobを実行。判断の根拠：×Cloud Storage（GCS）はHTMLやCSS等の静的ファイルを配信するだけで、Pythonコードの実行は不可（Flaskは動かない）。×Compute Engineはサーバーレスではなく「VMを自分で管理する」形態のため運用コストが高い。', 1),
  ('m3q20', 'サーバーレス', '複数の開発チームが隔離されたCassandra開発環境を必要としている。迅速かつ最小限のサポート作業で移行するには？', '["GCPにCassandraをインストールする手順書を作成し開発者に配布","開発者にCloud Marketplaceに行くようアドバイスし、Cassandraイメージを起動してもらう","Cassandra CEインスタンスを構築しスナップショットで開発者用インスタンスを作成","スナップショットをGCSにアップし、開発者向けの手順書を作成"]', 1, 'Marketplace＝事前構成済みイメージをワンクリックでデプロイ。各開発者がセルフサービスで独立した環境を作れる＝管理者のサポート作業最小。手順書方式は手間とミスの温床。', 2),
  ('m2q29', '監視・ログ', '単一のCompute Engineインスタンスのアプリがログをディスクに書き込む。ユーザーからエラー報告。問題を診断するには？', '["Cloud Loggingに移動してアプリケーションログを表示","ヘルスチェックを構成し正常しきい値を1に設定","シリアルコンソールに接続してログを読む","Opsエージェントをインストール・構成し、Cloud Loggingからログを表示"]', 3, 'VMのディスクに書かれたログはOps AgentなしではCloud Loggingに届かない。①Agentインストール→②Cloud Loggingで確認の順。Agentなしで直接Cloud Loggingに行っても何もない。', 2),
  ('m3q11', '監視・ログ', '外部監査人に監査ログとデータアクセスログをレビューする権限が必要。どうすべき？', '["roles/logging.privateLogViewerを割り当て、ログをGCSにエクスポート","roles/logging.privateLogViewerを割り当て、IAMポリシー変更ログのレビューも指示","logging.privateLogEntries.list権限のカスタムロール＋GCSエクスポート","logging.privateLogEntries.list権限のカスタムロール＋レビュー指示"]', 1, 'privateLogViewerは監査ログ＋データアクセスログ両方を見られる事前定義ロール。直接ログエクスプローラでレビューでき、エクスポートは不要。カスタムロールは事前定義で足りる場合は作らない。', 1),
  ('m3q12', '監視・ログ', '複数プロジェクトの過去60日分の全ログにアクセスし、内容を探索・迅速に分析したい。Googleの推奨は？', '["Stackdriver Loggingでresource.labels.project_id=\"*\"を選択","BigQueryデータセットをシンク先とするLogging Exportを作成し、テーブル有効期限を60日に設定","Cloud Storageをシンク先とするExport＋60日のライフサイクルルール","Cloud SchedulerジョブでStackdriverから読み取りBigQueryに保存"]', 1, 'Cloud Loggingのデフォルト保持は30日＝60日分にはエクスポート必須。「探索・迅速な分析」＝SQL＝BigQuery。GCSは長期保管向きで分析は苦手。Schedulerでのカスタム実装は不要。', 1),
  ('m3q15', '監視・ログ', '退職した従業員のアクセス権が2週間後に削除された。退職後に機密性の高い顧客情報へアクセスしたか確認するには？', '["システムイベントログでプリンシパルとしてメールアドレスを検索","システムイベントログでユーザーに関連するSAを検索","データアクセス監査ログでプリンシパルとしてメールアドレスを検索","管理アクティビティログでユーザーに関連するSAを検索"]', 2, '「データを見たか」＝データアクセス監査ログ。管理アクティビティ＝構成変更の記録。システムイベント＝Google側の自動動作で人の活動は記録しない。ユーザー特定はprincipalEmail（メールアドレス）。', 1),
  ('m3q23', '監視・ログ', 'プロジェクト内に複数アプリがある中、Apacheウェブサーバーが動くVMの当月ネットワーク送信（Egress）コストが100ドル超でメール通知したい。どうすべき？', '["プロジェクトに予算アラートをセットアップ（100ドル・100%・メール）","請求アカウントに予算アラートをセットアップ","請求データをBigQueryにエクスポートし、SQLでEgressコストを集計、100ドル超でメール送信するCloud Functions＋Cloud Schedulerで毎時実行","ApacheログをCloud Loggingにエクスポートし、HTTPレスポンスサイズ×単価で計算"]', 2, '予算アラートはプロジェクト/請求アカウント全体の総額のみで、特定VM・特定SKUの抽出は不可。細かい粒度のコスト監視＝BigQuery請求エクスポート＋SQL＋Functions＋Schedulerの王道構成。', 1),
  ('m3q30', '監視・ログ', 'VMにデプロイしたアプリがログをディスクに書き込む。エラー報告があり問題を診断したい。どうすべき？', '["Cloud Loggingに移動してアプリログを表示","シリアルコンソールに接続してログを読む","ヘルスチェックを構成し低い正常しきい値を設定","Cloud Loggingエージェントをインストール・構成しCloud Loggingからログを表示"]', 3, 'ディスク上のログはエージェント（Ops Agent）なしではCloud Loggingに送信されない。エージェントのインストールが先、Cloud Loggingでの表示は後。', 2),
  ('m3q38', '監視・ログ', 'プロジェクトA、B、Cのアプリパフォーマンス（CPU・メモリ・ディスク）を単一ビューで監視したい。どうすべき？', '["APIを有効にし、各プロジェクトからグラフを共有","APIを有効にし、各プロジェクトにmetrics.readerロールを付与","APIを有効にし、デフォルトダッシュボードで全プロジェクトを順番に表示","APIを有効にし、プロジェクトAの下にワークスペースを作成しBとCを追加"]', 3, '複数プロジェクトの統合監視＝Cloud Monitoringワークスペース。ホストプロジェクト（A）を決めて監視対象（B・C）を追加する。ロール付与は権限の話で統合ビューの機能ではない。', 1),
  ('m3q39', '監視・ログ', '異なる請求アカウントにリンクされた複数プロジェクトの全コストを、単一の視覚的表現で確認したい。新しいコストデータを早く反映したい。どうすべき？', '["BigQueryへの請求データエクスポートを構成し、Data Studioで可視化","請求テーブルページからCSVエクスポートしData Studioで可視化","料金計算ツールで全リソースを入力し月額見積もりを取得","Cloud Billing Consoleのレポートビューで表示"]', 0, 'BigQuery請求エクスポートはほぼリアルタイムで詳細データを集約。Looker Studio（旧Data Studio）で可視化が王道。CSVは手動で非効率。料金計算ツールは未来の見積もり用。', 1),
  ('m2q11', 'データ分析', 'IoTアプリの数百万センサーが構造化・非構造化データを常時ストリーミング。高可用・回復性の高いデータレイクを構築するには？', '["データをPub/Subにストリーミングし、DataflowでCloud Storageに送信","データをPub/Subにストリーミングし、Storage Transfer ServiceでBigQueryに送信","Dataflowにストリーミングし、Dataprep by TrifactaでBigtableに送信","Dataflowにストリーミングし、Storage Transfer ServiceでBigQueryに送信"]', 0, 'ストリーミングの入口＝Pub/Sub（バッファリングで回復性）。変換＝Dataflow。データレイクの生データ層＝Cloud Storage。Storage Transfer Serviceはバッチ転送用でストリーミング不可。', 1),
  ('m3q44', 'データ分析', 'Spannerのバックアップ（Cloud Storage上）とBigtableのイベントログを、特定ユーザーについて結合するアドホックな依頼。最も効率的な方法は？', '["BigtableとCloud StorageからコピーするDataflowジョブを作成","BigtableとSpannerからコピーするDataflowジョブを作成","Dataprocクラスタを作成しSparkジョブでデータ抽出","Cloud StorageとBigtableに2つのBigQuery外部テーブルを作成し、ユーザーフィールドで結合"]', 3, 'アドホック（1回限り）の分析＝BigQuery外部テーブル。データを移動せずにSQLで直接クエリ・結合できる。Dataflow/Dataprocはパイプライン構築用で1回の調査には過剰。', 1),
  ('m3q1', '運用・CLI', 'UbuntuパッケージリポジトリからCloud SDKをインストール済み。ローカルでCloud Datastoreを使うアプリをテストするには？', '["gcloud datastore exportでデータをエクスポート","gcloud datastore indexes createでインデックスを作成","apt-get installでgoogle-cloud-sdk-datastore-emulatorをインストール","gcloud components installでcloud-datastore-emulatorをインストール"]', 2, 'SDKのインストール方法とコンポーネント追加方法は一致させる。apt経由でインストールしたなら追加コンポーネントもapt-get。gcloud components installはtarball手動インストールの場合のみ。', 1),
  ('m2q30', '運用・CLI', '新プロジェクトでインスタンス作成・FW設定・Cloud Storageへのデータ保存が必要。Googleの推奨に従うには？', '["gcloud servicesでcloudresourcemanager APIを有効にして全リソースを有効化","gcloud servicesでcompute APIとstorage APIを個別に有効化","コンソールのAPIダッシュボードから全Google Cloud APIを有効化","Cloud Shellでgcloud init --projectを実行"]', 1, '新プロジェクトではサービスごとにAPIの有効化が必要。必要なAPIだけを有効化するのが最小権限の原則。「全API有効化」は攻撃対象領域を増やす。gcloud initは初期設定でAPI有効化ではない。', 1),
  ('m2q49', '運用・CLI', 'プロキシ認証情報がgcloud CLIのログに記録されることを防ぐには？', '["gcloud config set proxy/username・proxy/passwordで構成","sha256でエンコードしcustom_ca_certs_fileに設定","構成ファイルにCLOUDSDK_PROXY_USERNAME/PASSWORDを記述","環境変数でCLOUDSDK_PROXY_USERNAME/PASSWORDを設定"]', 3, '機密情報は環境変数で渡す＝ログやファイルに残らない。config setや構成ファイル直書きは平文保存で漏洩リスク。sha256は不可逆ハッシュで認証情報として使えない。', 1),
  ('m3q18', '運用・CLI', '可能な限り少ないステップで複数のGCPプロジェクトを管理したい。gcloud CLIをどう構成すべき？', '["プロジェクトごとに構成を作成し、作業時に適切な構成をactivateで有効化","プロジェクトごとに構成を作成し、gcloud initで構成値を更新","1プロジェクトにデフォルト構成を使い、作業時にactivate","1プロジェクトにデフォルト構成を使い、gcloud initで更新"]', 0, 'gcloud config configurations＝プロジェクトごとの名前付き構成を作成し、activateで高速切り替え。gcloud initは新規初期化用で繰り返しの切り替えには非効率。', 1),
  ('m3q36', '運用・CLI', 'ほとんどのVMがeurope-west1-dゾーンで稼働。各CLIコマンドでゾーン指定する手間を省くには？', '["gcloud configサブコマンドでeurope-west1-dをデフォルトゾーンに設定","Compute Engineの設定ページでデフォルトロケーションを設定","CLIのインストールディレクトリにdefault.confを作成","compute/zoneキーのメタデータエントリを作成"]', 0, 'gcloud config set compute/zone europe-west1-d でデフォルトゾーンを設定。メタデータはインスタンス自身が使う情報でCLIには影響しない。default.confという仕組みは存在しない。', 1)
